<?php
namespace Modules\Ran\Http\Controllers;use Modules\Ran\Entities\{Payment,Sale};use Modules\Ran\Http\Requests\CustomerPaymentRequest;use Modules\Ran\Integrations\{CustomerIntegrationService,FinanceIntegrationService};use Modules\Ran\Services\CustomerPaymentService;
class CustomerPaymentController extends RanController{public function __construct(private CustomerPaymentService $service,private CustomerIntegrationService $customers,private FinanceIntegrationService $finance){}public function index(){return view('ran::customer-payments.index',['payments'=>Payment::query()->with('customer','sale')->latest('payment_date')->paginate(25)]);}public function create(){return view('ran::customer-payments.form',array_merge($this->pageOptions(),['customers'=>$this->customers->dropdown(),'accounts'=>$this->finance->dropdown(),'sales'=>Sale::query()->where('status','posted')->where('balance_amount','>',0)->latest('invoice_date')->get()]));}public function store(CustomerPaymentRequest $r){$this->service->create($r->validated());return $this->success('Customer payment posted.','ran.customer-payments.index');}}
